زمان تحویل تأمین‌کننده C یک‌باره خیلی زیاد شده. چه رخدادی بود؟ (مدیر خرید — شرکت مس کالسیمین)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "supplier_performance",
      "description": "عملکرد تأمین‌کنندگان: تأخیر، کیفیت، قیمت",
      "dimensions": [
        "supplier",
        "period"
      ],
      "measures": [
        "on_time_pct",
        "quality_score",
        "lead_time_days"
      ]
    },
    {
      "dataset": "inventory_critical",
      "description": "موجودی قطعات حیاتی و نقطهٔ سفارش",
      "dimensions": [
        "item"
      ],
      "measures": [
        "current_stock",
        "reorder_point",
        "lead_time_days"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "lead_time",
      "description": "زمان تحویل تأمین‌کننده",
      "formula": "روز از سفارش تا تحویل",
      "unit": "روز",
      "dimensions": [
        "supplier",
        "item"
      ]
    },
    {
      "metric": "supplier_on_time",
      "description": "نرخ تحویل به‌موقع",
      "formula": "تحویل‌های به‌موقع / کل تحویل‌ها",
      "unit": "درصد",
      "dimensions": [
        "supplier"
      ]
    }
  ],
  "business_context": [
    "خرید مواد اولیه، قطعات یدکی و مصرفی معدن از تأمین‌کنندگان داخلی و خارجی",
    "قراردادهای بلندمدت و سالانه با تأمین‌کنندگان اصلی",
    "تأمین قطعات حیاتی تجهیزات معدنی با زمان تحویل طولانی"
  ]
}

TOOL_CALL:
{
  "tool": "get_timeseries",
  "arguments": {
    "metric": "lead_time",
    "granularity": "month",
    "range": "last_6_months"
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "supplier_performance",
    "filters": {
      "supplier": "تأمین‌کننده C",
      "period": "last_3_months"
    }
  }
}

TOOL_OBSERVATION:
{
  "on_time_pct": {
    "تأمین‌کننده C": {
      "ماه_قبل": 92,
      "این_ماه": 65
    }
  },
  "note": "تأمین‌کننده C: مشکل تولید (آتش‌سوزی کارخانه) و تأخیر حمل دریایی"
}

نقش سازمانی: مدیر خرید و تدارکات (procurement_manager)

درخواست کاربر:
انحراف قیمت لاستیک شاول 17.5% است. ریشهٔ این افزایش کجاست؟ (مدیر خرید — شرکت مس شهید باهنر)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "purchase_orders",
      "description": "سفارشات خرید به تفکیک تأمین‌کننده و قلم",
      "dimensions": [
        "supplier",
        "item",
        "period"
      ],
      "measures": [
        "quantity",
        "unit_price",
        "total_cost"
      ]
    },
    {
      "dataset": "contracts",
      "description": "قراردادهای خرید: قیمت، حجم، مدت",
      "dimensions": [
        "supplier",
        "item"
      ],
      "measures": [
        "volume",
        "price_per_unit",
        "start_date",
        "end_date"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "purchase_price_variance",
      "description": "انحراف قیمت خرید",
      "formula": "(قیمت واقعی - قیمت برنامه‌ریزی‌شده) / قیمت برنامه‌ریزی‌شده",
      "unit": "درصد",
      "dimensions": [
        "item"
      ]
    }
  ],
  "business_context": [
    "خرید مواد اولیه، قطعات یدکی و مصرفی معدن از تأمین‌کنندگان داخلی و خارجی",
    "قراردادهای بلندمدت و سالانه با تأمین‌کنندگان اصلی",
    "تأمین قطعات حیاتی تجهیزات معدنی با زمان تحویل طولانی"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "purchase_orders",
    "filters": {
      "period": "curr_month",
      "ppv_above_zero": true
    }
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "contracts",
    "filters": {
      "item": "لاستیک شاول"
    }
  }
}

TOOL_OBSERVATION:
{
  "contract_status": "قرارداد سالانه با قیمت ثابت — منقضی شده و قرارداد جدید با قیمت بالاتر بسته شده",
  "market_note": "قیمت جهانی لاستیک ۱۲٪ افزایش یافته"
}

