    },
    {
      "name": "تأمین‌کننده B",
      "on_time": 94,
      "ppv": 7.0,
      "lead_time": 23
    },
    {
      "name": "تأمین‌کننده C",
      "on_time": 89,
      "ppv": 6.1,
      "lead_time": 18
    },
    {
      "name": "تأمین‌کننده D",
      "on_time": 86,
      "ppv": 2.9,
      "lead_time": 29
    },
    {
      "name": "تأمین‌کننده E",
