انحراف قیمت لاستیک شاول 22.5% است. ریشهٔ این افزایش کجاست؟ (مدیر خرید — مجتمع مس سرچشمه)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "purchase_orders",
      "description": "سفارشات خرید به تفکیک تأمین‌کننده و قلم",
      "dimensions": [
        "supplier",
        "item",
        "period"
      ],
      "measures": [
        "quantity",
        "unit_price",
        "total_cost"
      ]
    },
    {
      "dataset": "contracts",
      "description": "قراردادهای خرید: قیمت، حجم، مدت",
      "dimensions": [
        "supplier",
        "item"
      ],
      "measures": [
        "volume",
        "price_per_unit",
        "start_date",
        "end_date"
      ]
