زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "purchase_orders",
      "description": "سفارشات خرید به تفکیک تأمین‌کننده و قلم",
      "dimensions": [
        "supplier",
        "item",
        "period"
      ],
      "measures": [
        "quantity",
        "unit_price",
        "total_cost"
      ]
