نقش سازمانی: مدیر خرید و تدارکات (procurement_manager)

درخواست کاربر:
زمان تحویل تأمین‌کننده A یک‌باره خیلی زیاد شده. چه رخدادی بود؟ (مدیر خرید — شرکت مس کالسیمین)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "supplier_performance",
      "description": "عملکرد تأمین‌کنندگان: تأخیر، کیفیت، قیمت",
      "dimensions": [
        "supplier",
        "period"
      ],
      "measures": [
        "on_time_pct",
        "quality_score",
        "lead_time_days"
      ]
    },
    {
      "dataset": "inventory_critical",
      "description": "موجودی قطعات حیاتی و نقطهٔ سفارش",
      "dimensions": [
        "item"
      ],
      "measures": [
        "current_stock",
        "reorder_point",
        "lead_time_days"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "lead_time",
      "description": "زمان تحویل تأمین‌کننده",
      "formula": "روز از سفارش تا تحویل",
      "unit": "روز",
      "dimensions": [
        "supplier",
        "item"
      ]
    },
    {
      "metric": "supplier_on_time",
      "description": "نرخ تحویل به‌موقع",
      "formula": "تحویل‌های به‌موقع / کل تحویل‌ها",
      "unit": "درصد",
      "dimensions": [
        "supplier"
      ]
    }
  ],
  "business_context": [
    "خرید مواد اولیه، قطعات یدکی و مصرفی معدن از تأمین‌کنندگان داخلی و خارجی",
    "قراردادهای بلندمدت و سالانه با تأمین‌کنندگان اصلی",
    "تأمین قطعات حیاتی تجهیزات معدنی با زمان تحویل طولانی"
  ]
}

TOOL_CALL:
{
  "tool": "get_timeseries",
  "arguments": {
    "metric": "lead_time",
    "granularity": "month",
    "range": "last_6_months"
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "supplier_performance",
    "filters": {
      "supplier": "تأمین‌کننده A",
      "period": "last_3_months"
    }
  }
}

TOOL_OBSERVATION:
{
  "on_time_pct": {
    "تأمین‌کننده A": {
      "ماه_قبل": 92,
      "این_ماه": 65
    }
  },
  "note": "تأمین‌کننده A: مشکل تولید (آتش‌سوزی کارخانه) و تأخیر حمل دریایی"
}

